//! SCAN.MESHOP.PROV acceptance tests. Expected digests, flags and records are in
//! `fixtures/scan/meshop/prov_cases.txt`, written by the independent Python reference
//! `fixtures/scan/meshop/make_prov_cases.py` from the spec's builder rules; nothing here was
//! generated by running this crate. The test operations below are the ones that script
//! simulates. The quality reports inside the records come from the SCAN.POLY.QUAL reference
//! fixtures, which tests/quality.rs checks against this crate.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::cell::Cell;

use fid_geo_types::{digest_mesh, FrameRef, Mesh};
use fid_kci::kci::sha256;
use fid_scan_mesh::op::RECORD_KIND;
use fid_scan_mesh::{
    check_input_intact, MeshOp, MeshOpBuilder, MeshOpError, MeshOpLimits, MeshView, OpParams, ParamsWriter, Registered,
    RunOptions, Synthesized, TriRef, VerifiedMeshView,
};
use fid_types::{Determinism, Digest};

// ---------------------------------------------------------------- fixtures

fn read(rel: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/{rel}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn load_mesh(name: &str) -> Mesh {
    let text = read(&format!("{name}.txt"));
    let mut frame = None;
    let (mut v, mut t) = (Vec::new(), Vec::new());
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
        let parts: Vec<&str> = line.split(' ').collect();
        match parts[0] {
            "frame" => {
                let mut b = [0u8; 16];
                for (i, byte) in b.iter_mut().enumerate() {
                    *byte = u8::from_str_radix(&parts[1][2 * i..2 * i + 2], 16).unwrap();
                }
                frame = Some(FrameRef::from_bytes(b));
            }
            "v" => v.push([parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap()]),
            "t" => t.push([parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap()]),
            other => panic!("unknown line kind {other}"),
        }
    }
    Mesh::from_points(frame.unwrap(), &v, &t).unwrap()
}

fn open_cube() -> Mesh {
    load_mesh("mesh_open_cube")
}

/// One `case` block of the reference file, as key -> value.
fn case(name: &str) -> Vec<(String, String)> {
    let text = read("meshop/prov_cases.txt");
    let mut out = Vec::new();
    let mut inside = false;
    for line in text.lines() {
        let (k, v) = line.split_once(' ').unwrap_or((line, ""));
        if k == "case" {
            inside = v == name;
            continue;
        }
        if inside {
            if k == "end" {
                return out;
            }
            out.push((k.to_string(), v.to_string()));
        }
    }
    panic!("no case {name}");
}

fn get<'a>(c: &'a [(String, String)], key: &str) -> &'a str {
    &c.iter().find(|(k, _)| k == key).unwrap_or_else(|| panic!("no key {key}")).1
}

fn digest(c: &[(String, String)], key: &str) -> Digest {
    Digest::parse(get(c, key)).unwrap()
}

fn flag_string(s: &Synthesized) -> String {
    (0..s.len()).map(|t| if s.get(t).unwrap() { '1' } else { '0' }).collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

/// Checks everything common to the reference cases.
/// The record (quality reports included: the open and closed cube reports of this crate
/// equal the SCAN.POLY.QUAL reference byte for byte) and its digest are compared exactly.
fn check_case(name: &str, out: &fid_scan_mesh::MeshOpOutput) {
    let c = case(name);
    assert_eq!(out.inputs(), &[digest(&c, "input_digest")], "{name}: inputs");
    assert_eq!(out.output_digest(), digest(&c, "output_digest"), "{name}: output digest");
    assert_eq!(digest_mesh(out.mesh()).to_digest(), digest(&c, "output_element_digest"), "{name}: mesh");
    assert_eq!(out.mesh().vertex_count().to_string(), get(&c, "vertices"), "{name}");
    assert_eq!(out.mesh().triangle_count().to_string(), get(&c, "triangles"), "{name}");
    assert_eq!(out.synthesized().count().to_string(), get(&c, "synthesized"), "{name}");
    assert_eq!(flag_string(out.synthesized()), get(&c, "flags"), "{name}");
    assert_eq!(hex(&out.synthesized().to_bytes().unwrap()), get(&c, "flag_bytes"), "{name}");
    if c.iter().any(|(k, _)| k == "record") {
        let got = String::from_utf8(out.record_json().to_vec()).unwrap();
        assert_eq!(got, get(&c, "record"), "{name}: record");
        assert_eq!(out.record_digest(), Digest::from_bytes(sha256(out.record_json())), "{name}");
        assert_eq!(out.record_digest(), digest(&c, "record_digest"), "{name}: record digest");
    }
}

/// A raw measured mesh, verified against the digest it is stored by. These tests have no
/// store; the stored digest stands in as the mesh's element digest (for the open cube it is
/// also checked against the reference's `open_cube_digest` in AC-1).
fn raw(mesh: &Mesh) -> VerifiedMeshView<'_> {
    MeshView::unflagged(mesh).verified(&digest_mesh(mesh).to_digest()).unwrap()
}

/// The output of a run as the next run's input, verified against its recorded digest.
fn derived(out: &fid_scan_mesh::MeshOpOutput) -> VerifiedMeshView<'_> {
    MeshView::of_output(out).unwrap().verified(&out.output_digest()).unwrap()
}

// ---------------------------------------------------------------- test operations

fn copy_all_vertices(inputs: &[VerifiedMeshView<'_>], out: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
    for v in 0..inputs[0].mesh().vertex_count() {
        out.copy_vertex(0, v)?;
    }
    Ok(())
}

struct FillParams;
impl OpParams for FillParams {
    fn write(&self, w: &mut ParamsWriter) -> Result<(), MeshOpError> {
        w.str("face", "z0")
    }
}

/// Copies the open cube and fills the missing z = 0 face with two new triangles.
struct Fill;
impl MeshOp for Fill {
    const ID: &'static str = "mesh.test_fill@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = FillParams;
    fn run(
        &self,
        inputs: &[VerifiedMeshView<'_>],
        _: &FillParams,
        out: &mut MeshOpBuilder<'_, '_>,
    ) -> Result<(), MeshOpError> {
        copy_all_vertices(inputs, out)?;
        for t in 0..inputs[0].mesh().triangle_count() {
            out.copy_triangle(TriRef::new(0, t))?;
        }
        out.create_triangle([0, 2, 1])?;
        out.create_triangle([0, 3, 2])?;
        Ok(())
    }
}

struct SplitParams(Vec<u64>);
impl OpParams for SplitParams {
    fn write(&self, w: &mut ParamsWriter) -> Result<(), MeshOpError> {
        let s: Vec<String> = self.0.iter().map(|t| t.to_string()).collect();
        w.str("triangles", &s.join(" "))
    }
}

fn mid(p: [f64; 3], q: [f64; 3]) -> [f64; 3] {
    [0.5 * (p[0] + q[0]), 0.5 * (p[1] + q[1]), 0.5 * (p[2] + q[2])]
}

/// Splits the listed triangles into four at their edge midpoints.
struct Split;
impl MeshOp for Split {
    const ID: &'static str = "mesh.test_split@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = SplitParams;
    fn run(
        &self,
        inputs: &[VerifiedMeshView<'_>],
        p: &SplitParams,
        out: &mut MeshOpBuilder<'_, '_>,
    ) -> Result<(), MeshOpError> {
        let m = inputs[0].mesh();
        copy_all_vertices(inputs, out)?;
        for t in 0..m.triangle_count() {
            if !p.0.contains(&t) {
                out.copy_triangle(TriRef::new(0, t))?;
                continue;
            }
            let tri = m.triangle(t).unwrap();
            let [a, b, c] = tri.map(|v| out.copy_vertex(0, v).unwrap());
            let [pa, pb, pc] = tri.map(|v| m.vertex(v).unwrap());
            let mab = out.add_vertex(mid(pa, pb))?;
            let mbc = out.add_vertex(mid(pb, pc))?;
            let mca = out.add_vertex(mid(pc, pa))?;
            for kid in [[a, mab, mca], [mab, b, mbc], [mca, mbc, c], [mab, mbc, mca]] {
                out.derive_triangle(&[TriRef::new(0, t)], kid)?;
            }
        }
        Ok(())
    }
}

struct Seed(u64);
impl OpParams for Seed {
    fn write(&self, _: &mut ParamsWriter) -> Result<(), MeshOpError> {
        Ok(())
    }
    fn seed(&self) -> Option<u64> {
        Some(self.0)
    }
}

struct SplitMix(u64);
impl SplitMix {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
}

/// Copies the open cube with triangle 0 re-created from its own vertices, so flagged
/// synthesized: the flagged input of AC-2 (callers cannot attach flags directly).
struct Mark;
impl MeshOp for Mark {
    const ID: &'static str = "mesh.test_mark@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = ();
    fn run(&self, inputs: &[VerifiedMeshView<'_>], _: &(), out: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
        let m = inputs[0].mesh();
        copy_all_vertices(inputs, out)?;
        let tri = m.triangle(0).unwrap().map(|v| out.copy_vertex(0, v).unwrap());
        out.create_triangle(tri)?;
        for t in 1..m.triangle_count() {
            out.copy_triangle(TriRef::new(0, t))?;
        }
        Ok(())
    }
}

/// Copies the triangles in a seeded random order (D2).
struct Shuffle;
impl MeshOp for Shuffle {
    const ID: &'static str = "mesh.test_shuffle@1";
    const DETERMINISM: Determinism = Determinism::D2;
    type Params = Seed;
    fn run(
        &self,
        inputs: &[VerifiedMeshView<'_>],
        p: &Seed,
        out: &mut MeshOpBuilder<'_, '_>,
    ) -> Result<(), MeshOpError> {
        copy_all_vertices(inputs, out)?;
        let mut order: Vec<u64> = (0..inputs[0].mesh().triangle_count()).collect();
        let mut rng = SplitMix(p.0);
        for i in (1..order.len()).rev() {
            let j = (rng.next() % (i as u64 + 1)) as usize;
            order.swap(i, j);
        }
        for t in order {
            out.copy_triangle(TriRef::new(0, t))?;
        }
        Ok(())
    }
}

/// Copies everything.
struct Identity;
impl MeshOp for Identity {
    const ID: &'static str = "mesh.test_identity@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = ();
    fn run(&self, inputs: &[VerifiedMeshView<'_>], _: &(), out: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
        copy_all_vertices(inputs, out)?;
        for t in 0..inputs[0].mesh().triangle_count() {
            out.copy_triangle(TriRef::new(0, t))?;
        }
        Ok(())
    }
}

/// Declares D3.
struct Tolerant;
impl MeshOp for Tolerant {
    const ID: &'static str = "mesh.test_tolerant@1";
    const DETERMINISM: Determinism = Determinism::D3;
    type Params = ();
    fn run(&self, _: &[VerifiedMeshView<'_>], _: &(), _: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
        Ok(())
    }
}

/// Runs a closure as the operation (negative cases).
struct With<F>(F);
impl<F: Fn(&[VerifiedMeshView<'_>], &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError>> MeshOp for With<F> {
    const ID: &'static str = "mesh.test_with@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = ();
    fn run(&self, inputs: &[VerifiedMeshView<'_>], _: &(), out: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
        (self.0)(inputs, out)
    }
}

fn run_with<F>(inputs: &[VerifiedMeshView<'_>], f: F) -> Result<fid_scan_mesh::MeshOpOutput, MeshOpError>
where
    F: Fn(&[VerifiedMeshView<'_>], &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError>,
{
    Registered::new(With(f)).unwrap().run(inputs, &())
}

// ---------------------------------------------------------------- acceptance criteria

/// AC-1: fill the open cube's missing face: exactly two synthesized triangles, the input
/// digest unchanged and listed in the record.
#[test]
fn ac1_fill_open_cube() {
    let mesh = open_cube();
    let stored = read("meshop/prov_cases.txt");
    let stored = stored.lines().find_map(|l| l.strip_prefix("open_cube_digest ")).unwrap();
    let before = Digest::parse(stored).unwrap();
    let view = MeshView::unflagged(&mesh).verified(&before).unwrap();
    let out = Registered::new(Fill).unwrap().run(&[view], &FillParams).unwrap();
    assert_eq!(out.synthesized().count(), 2);
    assert_eq!(out.synthesized().get(10), Some(true));
    assert_eq!(out.synthesized().get(11), Some(true));
    assert_eq!(digest_mesh(&mesh).to_digest(), before, "input unchanged");
    check_input_intact(view.view(), &before).unwrap();
    assert_eq!(out.inputs(), &[before]);
    assert_eq!(out.params_json(), br#"{"face":"z0"}"#);
    assert_eq!(out.seed(), None);
    assert_eq!(out.determinism(), Determinism::D0);
    assert_eq!(out.op().as_str(), "mesh.test_fill@1");
    // REQ-005: quality before and after. The filled cube is closed.
    assert_eq!(out.quality_before().len(), 1);
    assert_eq!(out.quality_before()[0].boundary_edges, 4);
    assert_eq!(out.quality_after().boundary_edges, 0);
    assert_eq!(out.quality_after().triangles, 12);
    check_case("fill", &out);
    let rec = String::from_utf8(out.record_json().to_vec()).unwrap();
    assert!(rec.contains(&format!("\"kind\":\"{RECORD_KIND}\"")));
}

/// AC-2: splitting a synthesized triangle gives four synthesized children; splitting a
/// measured one gives four measured children.
#[test]
fn ac2_split_propagates_flags() {
    let mesh = open_cube();
    let marked = Registered::new(Mark).unwrap().run(&[raw(&mesh)], &()).unwrap();
    check_case("mark", &marked);
    assert_eq!(flag_string(marked.synthesized()), get(&case("split"), "input_flags"));
    let view = derived(&marked);
    assert_eq!(view.digest(), digest(&case("split"), "input_digest"));
    let out = Registered::new(Split).unwrap().run(&[view], &SplitParams(vec![0, 1])).unwrap();
    let s = out.synthesized();
    for t in 0..4 {
        assert_eq!(s.get(t), Some(true), "child {t} of the synthesized triangle");
    }
    for t in 4..8 {
        assert_eq!(s.get(t), Some(false), "child {t} of the measured triangle");
    }
    check_case("split", &out);
    assert_eq!(out.params_json(), br#"{"triangles":"0 1"}"#);
}

/// AC-3: a D3 operation fails registration with `scan.mesh.bad_determinism`.
#[test]
fn ac3_d3_rejected_at_registration() {
    let e = Registered::new(Tolerant).unwrap_err();
    assert_eq!(e, MeshOpError::BadDeterminism(Determinism::D3));
    assert_eq!(e.code(), "scan.mesh.bad_determinism");
}

/// AC-4: a D2 operation run twice with one seed gives equal output digests, and the seed
/// is in the record; another seed gives another (reference) result.
#[test]
fn ac4_d2_seed_recorded_and_reproducible() {
    let mesh = open_cube();
    let reg = Registered::new(Shuffle).unwrap();
    let view = raw(&mesh);
    let a = reg.run(&[view], &Seed(42)).unwrap();
    let b = reg.run(&[view], &Seed(42)).unwrap();
    assert_eq!(a.output_digest(), b.output_digest());
    assert_eq!(a.record_digest(), b.record_digest());
    assert_eq!(a.record_json(), b.record_json());
    assert_eq!(a.seed(), Some(42));
    assert!(String::from_utf8(a.record_json().to_vec()).unwrap().contains("\"seed\":\"42\""));
    check_case("shuffle_42", &a);
    let c = reg.run(&[view], &Seed(7)).unwrap();
    check_case("shuffle_7", &c);
    assert_ne!(a.output_digest(), c.output_digest());
}

/// AC-5: an identity operation on a mesh without the attribute outputs the attribute, all
/// false; and the output never carries the digest of the raw measured input although its
/// geometry is bit-identical (D-045 spirit).
#[test]
fn ac5_identity_adds_all_false_attribute() {
    let mesh = open_cube();
    let view = raw(&mesh);
    assert!(!view.has_attribute());
    assert_eq!(view.synthesized(3), Some(false));
    let out = Registered::new(Identity).unwrap().run(&[view], &()).unwrap();
    assert_eq!(out.synthesized().len(), 10);
    assert_eq!(out.synthesized().count(), 0);
    check_case("identity", &out);
    assert_eq!(digest_mesh(out.mesh()).to_digest(), view.digest(), "same geometry");
    assert_ne!(out.output_digest(), view.digest(), "a derived mesh never has a raw digest");
    // Passing the bare output mesh off as raw data fails the digest check against the
    // recorded output version.
    let laundered = MeshView::unflagged(out.mesh());
    assert_eq!(laundered.verified(&out.output_digest()).unwrap_err().code(), "scan.mesh.digest_mismatch");
    let honest = derived(&out);
    assert!(honest.has_attribute());
}

/// Chaining: the identity of the fill output keeps its flags and cites its version.
#[test]
fn chain_keeps_flags_and_cites_derived_input() {
    let mesh = open_cube();
    let fill = Registered::new(Fill).unwrap().run(&[raw(&mesh)], &FillParams).unwrap();
    let view = derived(&fill);
    assert_eq!(view.digest(), fill.output_digest());
    let out = Registered::new(Identity).unwrap().run(&[view], &()).unwrap();
    assert_eq!(out.inputs(), &[fill.output_digest()]);
    assert_eq!(out.synthesized(), fill.synthesized());
    check_case("chain", &out);
}

// ---------------------------------------------------------------- refusals

#[test]
fn registration_and_seed_rules() {
    struct BadId;
    impl MeshOp for BadId {
        const ID: &'static str = "Mesh.Bad";
        const DETERMINISM: Determinism = Determinism::D0;
        type Params = ();
        fn run(&self, _: &[VerifiedMeshView<'_>], _: &(), _: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
            Ok(())
        }
    }
    assert_eq!(Registered::new(BadId).unwrap_err().code(), "scan.mesh.bad_op_id");

    struct NoSeedD2;
    impl MeshOp for NoSeedD2 {
        const ID: &'static str = "mesh.test_noseed@1";
        const DETERMINISM: Determinism = Determinism::D2;
        type Params = ();
        fn run(&self, _: &[VerifiedMeshView<'_>], _: &(), _: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
            Ok(())
        }
    }
    let mesh = open_cube();
    let view = raw(&mesh);
    assert_eq!(Registered::new(NoSeedD2).unwrap().run(&[view], &()).unwrap_err().code(), "scan.mesh.missing_seed");

    struct SeededD0;
    impl MeshOp for SeededD0 {
        const ID: &'static str = "mesh.test_seeded@1";
        const DETERMINISM: Determinism = Determinism::D0;
        type Params = Seed;
        fn run(&self, _: &[VerifiedMeshView<'_>], _: &Seed, _: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
            Ok(())
        }
    }
    let e = Registered::new(SeededD0).unwrap().run(&[view], &Seed(1)).unwrap_err();
    assert_eq!(e.code(), "scan.mesh.unexpected_seed");
}

#[test]
fn input_refusals() {
    let mesh = open_cube();
    assert_eq!(run_with(&[], |_, _| Ok(())).unwrap_err().code(), "scan.mesh.no_input");
    let other = Mesh::from_points(FrameRef::from_bytes([9; 16]), &[[0.0, 0.0, 0.0]], &[]).unwrap();
    let e = run_with(&[raw(&mesh), raw(&other)], |_, _| Ok(())).unwrap_err();
    assert_eq!(e, MeshOpError::FrameMismatch { input: 1 });
    let many = vec![raw(&mesh); fid_scan_mesh::op::MAX_INPUTS + 1];
    assert_eq!(run_with(&many, |_, _| Ok(())).unwrap_err().code(), "scan.mesh.too_many_inputs");
    let wrong = Digest::parse(&format!("sha256:{}", "ab".repeat(32))).unwrap();
    assert_eq!(MeshView::unflagged(&mesh).verified(&wrong).unwrap_err().code(), "scan.mesh.digest_mismatch");
    // The all-false output of an identity run, the one-flag output of Mark and the raw mesh
    // share their geometry but are three different versions; no caller can relabel one as
    // another.
    let none = Registered::new(Identity).unwrap().run(&[raw(&mesh)], &()).unwrap();
    let one = Registered::new(Mark).unwrap().run(&[raw(&mesh)], &()).unwrap();
    assert_eq!(digest_mesh(none.mesh()), digest_mesh(one.mesh()));
    let (d_raw, d_none, d_one) = (raw(&mesh).digest(), none.output_digest(), one.output_digest());
    assert!(d_raw != d_none && d_none != d_one && d_raw != d_one);
    let e = MeshView::of_output(&one).unwrap().verified(&d_none).unwrap_err();
    assert_eq!(e.code(), "scan.mesh.digest_mismatch");
    assert_eq!(check_input_intact(derived(&one).view(), &d_none).unwrap_err().code(), "scan.mesh.digest_mismatch");
}

#[test]
fn builder_refusals() {
    let mesh = open_cube();
    let views = [raw(&mesh)];
    let code = |f: &dyn Fn(&mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError>| {
        run_with(&views, |_, b| f(b)).unwrap_err().code()
    };
    assert_eq!(code(&|b| b.copy_triangle(TriRef::new(1, 0)).map(drop)), "scan.mesh.invalid_index");
    assert_eq!(code(&|b| b.copy_triangle(TriRef::new(0, 10)).map(drop)), "scan.mesh.invalid_index");
    assert_eq!(code(&|b| b.copy_vertex(0, 8).map(drop)), "scan.mesh.invalid_index");
    assert_eq!(code(&|b| b.create_triangle([0, 1, 2]).map(drop)), "scan.mesh.invalid_index");
    assert_eq!(code(&|b| b.derive_triangle(&[], [0, 0, 0]).map(drop)), "scan.mesh.no_source");
    assert_eq!(
        code(&|b| {
            b.copy_vertex(0, 0)?;
            b.derive_triangle(&[TriRef::new(0, 99)], [0, 0, 0]).map(drop)
        }),
        "scan.mesh.invalid_index"
    );
    assert_eq!(code(&|b| b.add_vertex([f64::NAN, 0.0, 0.0]).map(drop)), "scan.mesh.non_finite");
    assert_eq!(code(&|b| b.add_vertex([0.0, f64::INFINITY, 0.0]).map(drop)), "scan.mesh.non_finite");
    assert_eq!(code(&|_| Err(MeshOpError::Op { code: "scan.mesh.test_failure" })), "scan.mesh.test_failure");
    // copy_vertex maps one input vertex to one output vertex.
    let out = run_with(&views, |_, b| {
        let a = b.copy_vertex(0, 5)?;
        let again = b.copy_vertex(0, 5)?;
        assert_eq!((a, again), (0, 0));
        b.copy_triangle(TriRef::new(0, 0)).map(drop)
    })
    .unwrap();
    assert_eq!(out.mesh().vertex_count(), 3);
    assert_eq!(out.mesh().triangle(0), Some([1, 0, 2]));
}

#[test]
fn limits_bound_the_output() {
    let mesh = open_cube();
    let views = [raw(&mesh)];
    let reg = Registered::new(Identity).unwrap();
    let tight = |v: u64, t: u64| RunOptions {
        limits: MeshOpLimits { max_vertices: v, max_triangles: t, work_budget_bytes: None },
        ..RunOptions::default()
    };
    assert_eq!(reg.run_with(&views, &(), &tight(7, 100)).unwrap_err().code(), "scan.mesh.limit_exceeded");
    assert_eq!(reg.run_with(&views, &(), &tight(100, 9)).unwrap_err().code(), "scan.mesh.limit_exceeded");
    reg.run_with(&views, &(), &tight(8, 10)).unwrap();
    let budget = RunOptions {
        limits: MeshOpLimits { work_budget_bytes: Some(1), ..MeshOpLimits::default() },
        ..RunOptions::default()
    };
    assert_eq!(reg.run_with(&views, &(), &budget).unwrap_err().code(), "scan.mesh.invalid_output");
    for t in [0.0, -1e-18, f64::NAN, f64::INFINITY] {
        let bad = RunOptions { degenerate_area: t, ..RunOptions::default() };
        assert_eq!(reg.run_with(&views, &(), &bad).unwrap_err().code(), "scan.mesh.invalid_threshold", "{t}");
    }
}

/// The quality threshold is in the record, so a non-default run is reproducible from it
/// (hand-labelled ECMAScript forms).
#[test]
fn quality_threshold_recorded() {
    let mesh = open_cube();
    let reg = Registered::new(Identity).unwrap();
    let default = reg.run(&[raw(&mesh)], &()).unwrap();
    assert_eq!(default.quality_threshold(), "1e-18");
    let opts = RunOptions { degenerate_area: 1e-6, ..RunOptions::default() };
    let other = reg.run_with(&[raw(&mesh)], &(), &opts).unwrap();
    assert_eq!(other.quality_threshold(), "0.000001");
    let rec = String::from_utf8(other.record_json().to_vec()).unwrap();
    assert!(rec.contains(r#""quality_threshold":"0.000001","seed":null"#), "{rec}");
    assert_eq!(default.output_digest(), other.output_digest(), "same mesh");
    assert_ne!(default.record_digest(), other.record_digest(), "different record");
}

/// Parameters that cannot be recorded canonically stop the run before the operation.
#[test]
fn params_refused_before_run() {
    struct BadParams;
    impl OpParams for BadParams {
        fn write(&self, w: &mut ParamsWriter) -> Result<(), MeshOpError> {
            w.f64("max_move", f64::NAN)
        }
    }
    struct Counting<'c>(&'c Cell<u32>);
    impl MeshOp for Counting<'_> {
        const ID: &'static str = "mesh.test_counting@1";
        const DETERMINISM: Determinism = Determinism::D0;
        type Params = BadParams;
        fn run(
            &self,
            _: &[VerifiedMeshView<'_>],
            _: &BadParams,
            _: &mut MeshOpBuilder<'_, '_>,
        ) -> Result<(), MeshOpError> {
            self.0.set(self.0.get() + 1);
            Ok(())
        }
    }
    let runs = Cell::new(0);
    let mesh = open_cube();
    let e = Registered::new(Counting(&runs)).unwrap().run(&[raw(&mesh)], &BadParams).unwrap_err();
    assert_eq!(e.code(), "scan.mesh.bad_params");
    assert_eq!(runs.get(), 0);
}
